---arch/PowerPC/PPCInstPrinter.c:455
   455  static void printU1ImmOperand(MCInst *MI, unsigned OpNo, SStream *O)
   456  {
   457          unsigned int Value = (unsigned int)MCOperand_getImm(MCInst_getOperand(MI, OpNo));
   458
   459          // assert(Value <= 1 && "Invalid u1imm argument!");
   460
   461          printUInt32(O, Value);
   462
   463          if (MI->csh->detail) {
   464                  MI->flat_insn->detail->ppc.operands[MI->flat_insn->detail->ppc.op_count].type = PPC_OP_IMM;
   465                  MI->flat_insn->detail->ppc.operands[MI->flat_insn->detail->ppc.op_count].imm = Value;
   466                  MI->flat_insn->detail->ppc.op_count++;
   467          }
